// session-register (OpenCode 2 TUI) — auto-installed by the machine adapter. Tells the local machine
// daemon (127.0.0.1:19473) which session this pane shows, as the 1.x plugin does. No-op if machine isn't running.
import { readFileSync } from "node:fs"
const hookToken = () => { try { return readFileSync("<root>/data/hook-token", "utf8").trim() } catch { return "" } }
const harnessSocket = null
const harnessFetch = async (url, init) => {
  if (!harnessSocket) return fetch(url, init)
  const { lstatSync } = await import("node:fs")
  const { dirname } = await import("node:path")
  const { request } = await import("node:http")
  const uid = process.getuid?.()
  const file = lstatSync(harnessSocket), folder = lstatSync(dirname(harnessSocket))
  if (!file.isSocket() || (file.mode & 0o077) !== 0 || !folder.isDirectory() || (folder.mode & 0o022) !== 0
    || (uid !== undefined && (file.uid !== uid || folder.uid !== uid))) throw new Error("The Harness socket is not private.")
  return new Promise((resolve, reject) => {
    const asked = request({ socketPath: harnessSocket, method: init.method, path: new URL(url).pathname,
      headers: { ...init.headers, "content-length": String(Buffer.byteLength(init.body)) } }, (answer) => {
      answer.resume()
      answer.on("end", () => resolve({ ok: answer.statusCode >= 200 && answer.statusCode < 300, status: answer.statusCode }))
      answer.on("error", reject)
    })
    asked.on("error", reject)
    asked.end(init.body)
  })
}
export default {
  id: "harness-session-register",
  setup(ctx) {
    const pane = process.env.TMUX_PANE
    const ptyPane = pane ? null : /^(p\d{1,4}(?:-(?:[0-9A-Za-z.-]{1,32}|h[0-9a-f]{12}))?):(%\d{1,9})$/.exec(process.env.HARNESS_PANE || "")
    const router = ctx && ctx.ui && ctx.ui.router
    if ((!pane && !ptyPane) || !router || typeof router.current !== "function") return
    const posted = new Set()
    let busy = false
    const post = async (sessionID) => {
      const token = hookToken()
      if (!token || !sessionID || posted.has(sessionID) || busy) return
      busy = true
      try {
        let info
        try { info = await (ctx.data && ctx.data.session && ctx.data.session.get ? ctx.data.session.get(sessionID) : undefined) } catch {}
        if (info && info.parentID) { posted.add(sessionID); return } // a sub-agent's — shown under its parent's Task card
        const cwd = (info && info.location && info.location.directory) || (ctx.location && ctx.location.directory) || process.cwd()
        const res = await harnessFetch("http://127.0.0.1:19473/api/hook/session-start", {
          method: "POST",
          headers: { "content-type": "application/json", "x-harness-hook-token": token },
          body: JSON.stringify({
            engine: "opencode",
            pluginVersion: "<version>",
            sessionId: sessionID,
            cwd,
            tmuxPane: pane,
            callerPid: process.pid,
            runtimeHints: pane ? [{ backend: "tmux", paneId: pane }] : [{ backend: "ptyhost", instance: ptyPane[1], paneId: ptyPane[2] }],
          }),
        })
        if (res && res.ok) posted.add(sessionID)
      } catch {} finally { busy = false }
    }
    const check = () => {
      try { const at = router.current(); if (at && at.type === "session" && at.sessionID) post(at.sessionID) } catch {}
    }
    check()
    const timer = setInterval(check, 1000)
    if (timer && typeof timer.unref === "function") timer.unref()
    return () => clearInterval(timer)
  },
}

